package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 通用基础配置：统一注入 UTC 时钟，业务时间判断全部基于该时钟，测试中可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 系统默认 UTC 时钟；所有“当前时刻”均从该 Bean 获取，单元测试可覆盖为固定/可调时钟。
     */
    @Bean
    public Clock systemClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.domain;

/**
 * 潜次状态：作业申请生成方案后为 PLANNED，潜水执行中为 EXECUTING，
 * 出水观察中为 OBSERVING，观察期出现症状启动加压舱预案后为 CHAMBER（冻结结案），
 * 正常结案为终态 CLOSED。
 */
public enum OperationStatus {
    /** 已受理申请并生成减压方案，尚未开始潜水。 */
    PLANNED,
    /** 潜水执行中（已产生水下记录）。 */
    EXECUTING,
    /** 出水后 2 小时观察期内。 */
    OBSERVING,
    /** 观察期出现症状，已启动加压舱预案，结案被永久冻结。 */
    CHAMBER,
    /** 终态：已结案。 */
    CLOSED
}

package com.example.starter.domain;

/**
 * 水下记录分段类型：下潜、水底（作业）、出水（上升）。
 */
public enum DivePhase {
    /** 下潜段：由浅到深，速率不超过 18m/min。 */
    DESCEND,
    /** 水底作业段：不参与速率计算，计入水下时长。 */
    BOTTOM,
    /** 出水上升段：由深到浅，速率不超过 18m/min。 */
    ASCEND
}

