 */
@Repository
public class DivingRepository {

    private final JdbcTemplate jdbc;

    public DivingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final RowMapper<IdempotentRow> IDEMPOTENT_MAPPER = (rs, n) -> new IdempotentRow(
