package com.example.starter.service;

import java.time.Clock;

import org.springframework.stereotype.Service;

import com.example.starter.api.ApplicationRequest;
import com.example.starter.api.CloseRequest;
import com.example.starter.api.CloseResponse;
import com.example.starter.api.ExitRequest;
import com.example.starter.api.ExitResponse;
import com.example.starter.api.PlanChangeRequest;
import com.example.starter.api.PlanResponse;
import com.example.starter.api.SegmentRequest;
import com.example.starter.api.SegmentResponse;
import com.example.starter.api.VitalsRequest;
import com.example.starter.api.VitalsResponse;
import com.example.starter.repo.DivingRepository;

/**
 * 潜水作业主服务（骨架：方法签名固定，实现逐批填充）。
 * 潜次流转：作业申请 → 减压方案 → 潜水执行 → 出水观察 → 结案。
 */
@Service
public class DivingService {

    private final DivingRepository repository;
    private final Clock clock;

    public DivingService(DivingRepository repository, Clock clock) {
        this.repository = repository;
        this.clock = clock;
    }

    /** 作业申请：查合成减压表生成方案，同组同时刻唯一受理，requestId 幂等。 */
    public PlanResponse apply(ApplicationRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 方案变更：重查减压表；旧方案已生成记录与新方案在同一事务内冻结。 */
    public PlanResponse changePlan(PlanChangeRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 水下记录：两人成组提交方生效；速率恰 18 合格、超速告警；生效即入 24h 累计台账。 */
    public SegmentResponse recordSegment(SegmentRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 出水登记：进入观察期，观察期满 = exitAt + 7200 秒。 */
    public ExitResponse exit(ExitRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 观察期体征：症状触发加压舱预案冻结结案；结案后迟到数据仅登记事件。 */
    public VitalsResponse vitals(VitalsRequest request) {
        throw new UnsupportedOperationException();
    }

    /** 结案：恰满 2 小时观察且无症状方可结案；终态重复结案幂等成功。 */
    public CloseResponse close(CloseRequest request) {
        throw new UnsupportedOperationException();
    }
}

